  // notifications page has something to show and `pnpm worker` has work to do.
  const upcoming = inserted.filter((b) => b.status === "confirmed");
  if (upcoming.length > 0) {
    await db.insert(s.outbox).values(
      upcoming.flatMap((b) => [
        {
